"""``docker-compose.packages.yml`` as the second ``-f`` file."""

from __future__ import annotations

from collections.abc import Sequence
from pathlib import Path

from keystonectl.layout import WIRED_DIR

MIN_COMPOSE_VERSION = (2, 24, 0)
_HEADER = (
    "# Generated by keystonectl. Do not edit: this file is rewritten on every change.\n"
    "# Use: docker compose -f docker-compose.yml -f docker-compose.packages.yml up -d\n"
    "# Change a package in packages/<name>.override.yml instead.\n"
)


def parse_compose_version(text: str) -> tuple[int, ...] | None:
    """Parse ``docker compose version --short`` (``2.29.1`` or ``v2.24.0-desktop.1``)."""

    token = text.strip().split()[-1] if text.strip() else ""
    token = token.removeprefix("v")
    numbers: list[int] = []
    for part in token.split("."):
        digits = ""
        for char in part:
            if char.isdigit():
                digits += char
            else:
                break
        if not digits:
            break
        numbers.append(int(digits))
    if len(numbers) < 2:
        return None
    return tuple(numbers)


def compose_is_old(text: str) -> bool:
    parsed = parse_compose_version(text)
    if parsed is None:
        return True
    width = max(len(parsed), len(MIN_COMPOSE_VERSION))
    left = parsed + (0,) * (width - len(parsed))
    right = MIN_COMPOSE_VERSION + (0,) * (width - len(MIN_COMPOSE_VERSION))
    return left < right


def render_packages_file(
    *,
    keystone_service: str,
    packages: Sequence[tuple[str, bool]],
    attach_network: bool = True,
    include_default_network: bool = False,
) -> str:
    """Render the packages override file.

    ``packages`` is ``(name, override_exists)`` and is sorted by name here.
    An override is listed in the same ``path`` element as its fragment.
    """

    by_name: dict[str, bool] = {}
    for name, has_override in packages:
        by_name.setdefault(name, has_override)
    lines = [_HEADER.rstrip("\n")]
    if by_name:
        lines.append("include:")
        for name in sorted(by_name):
            if by_name[name]:
                lines.append("  - path:")
                lines.append(f"      - packages/{name}.yml")
                lines.append(f"      - packages/{name}.override.yml")
            else:
                lines.append(f"  - path: packages/{name}.yml")
    lines.append("services:")
    lines.append(f"  {keystone_service}:")
    lines.append("    environment:")
    lines.append(f"      KEYSTONE_MCP_UPSTREAMS_PATH: {WIRED_DIR}/upstreams.yaml")
    lines.append(f"      KEYSTONE_MCP_RBAC_CATALOG_SNAPSHOT: {WIRED_DIR}/catalog-snapshot.yaml")
    lines.append("    volumes:")
    lines.append("      - ./keystonectl:/etc/keystone-mcp/keystonectl:ro")
    if attach_network:
        if include_default_network:
            lines.append("    networks: [default, keystone-mcp-upstreams]")
        else:
            lines.append("    networks: [keystone-mcp-upstreams]")
        lines.append("networks:")
        lines.append("  keystone-mcp-upstreams:")
        lines.append("    name: keystone-mcp-upstreams")
        lines.append("    external: true")
    return "\n".join(lines) + "\n"


def override_is_present(path: Path) -> bool:
    """True when the operator override exists. Uses stat, never opens the file."""

    return path.is_file()
